import{af as a,z as t,J as i,ab as r}from"./chunks/framework.D-2fLa7v.js";const u=JSON.parse('{"title":"Understanding your device LEDs","description":"","frontmatter":{"aside":true,"order":1},"headers":[],"relativePath":"guides/leds.md","filePath":"guides/leds.md"}'),s={name:"guides/leds.md"};function o(d,e,n,c,h,l){return t(),i("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794316070000"},[...e[0]||(e[0]=[r('<h1 id="understanding-your-device-leds" tabindex="-1">Understanding your device LEDs <a class="header-anchor" href="#understanding-your-device-leds" aria-label="Permalink to &quot;Understanding your device LEDs&quot;">​</a></h1><p>Start with your device model and the situation: charging, starting up, responding to a button, or running an application. The same light can mean different things in those states.</p><p>The reusable LED features are documented as <a href="/docs/pr/40/devices/capabilities/">device capabilities</a>. This guide helps you choose the right capability and model-specific details rather than defining another set of LED patterns.</p><h2 id="identify-the-device-and-its-capabilities" tabindex="-1">Identify the device and its capabilities <a class="header-anchor" href="#identify-the-device-and-its-capabilities" aria-label="Permalink to &quot;Identify the device and its capabilities&quot;">​</a></h2><p>Check the product code on the label or in your device details. ProN (PR2) and Pro3 (PR3) share the same external appearance but have different indicators. Zero ZE2 and ZE3 are also different generations.</p><table tabindex="0"><thead><tr><th>Device</th><th>LED capabilities and model details</th></tr></thead><tbody><tr><td><a href="/docs/pr/40/devices/pro/">Pro3 / PR3</a></td><td><a href="/docs/pr/40/devices/capabilities/four-power-leds">Four power LEDs</a>; without separate GPS/GSM diagnostics</td></tr><tr><td><a href="/docs/pr/40/devices/history/PR2">ProN / PR2</a></td><td><a href="/docs/pr/40/devices/capabilities/four-power-leds">Four power LEDs</a> plus the older <a href="/docs/pr/40/devices/capabilities/gps-gsm-status-leds#pro-pr2">GPS/GSM pair</a></td></tr><tr><td><a href="/docs/pr/40/devices/zero/">Zero / ZE2</a></td><td><a href="/docs/pr/40/devices/capabilities/four-power-leds">Four power LEDs</a> plus the older <a href="/docs/pr/40/devices/capabilities/gps-gsm-status-leds#zero-ze2">GPS/GSM pair</a></td></tr><tr><td><a href="/docs/pr/40/devices/enviro/">Enviro / EN2</a></td><td><a href="/docs/pr/40/devices/capabilities/four-power-leds">Four power LEDs</a> plus the older <a href="/docs/pr/40/devices/capabilities/gps-gsm-status-leds#enviro-en2">GPS/GSM pair</a></td></tr><tr><td><a href="/docs/pr/40/devices/vehicle/">Vehicle / VT3</a></td><td><a href="/docs/pr/40/devices/capabilities/four-power-leds">Four power LEDs</a>, also used for its <a href="/docs/pr/40/devices/vehicle/#vehicle-connection-status">connection display</a></td></tr><tr><td><a href="/docs/pr/40/devices/rtk/handheld/">Handheld RTK / RH2</a></td><td><a href="/docs/pr/40/devices/capabilities/rgb-status-leds">RGB status LEDs</a>; see the <a href="/docs/pr/40/devices/rtk/handheld/leds">RH2-specific colours and application feedback</a></td></tr></tbody></table><p>For other devices or earlier generations, use the matching <a href="/docs/pr/40/devices">device documentation</a> or <a href="/docs/pr/40/devices/history/">legacy pages</a>, or ask support. Do not borrow a colour table from a similar-looking device.</p><h2 id="check-what-is-happening" tabindex="-1">Check what is happening <a class="header-anchor" href="#check-what-is-happening" aria-label="Permalink to &quot;Check what is happening&quot;">​</a></h2><ol><li><strong>Starting up?</strong> Wait for startup to finish. On PR2, <a href="/docs/pr/40/devices/history/PR2#two-red-lights-and-four-orange-lights-after-a-restart">two red lights and four orange lights can appear during startup</a>. That is not the Pro3 layout or a universal fault code.</li><li><strong>Charging?</strong> Use either <a href="/docs/pr/40/devices/capabilities/four-power-leds#charging">four power LED charging patterns</a> or the <a href="/docs/pr/40/devices/rtk/handheld/leds#charging-status">RH2 RGB charging table</a>, as appropriate. Do not mix their thresholds.</li><li><strong>Just pressed a button?</strong> A brief status display may finish and go dark. On VT3 the same indicators can also show ignition and charging.</li><li><strong>Running an application or alarm?</strong> Its feedback can replace standard status. For example, <a href="/docs/pr/40/devices/rtk/handheld/leds#application-controlled-feedback">RH2 Survey submission flashes</a> are application events, not battery colours.</li></ol><p>No lights does not necessarily mean the tracker is off or empty. Many devices turn their lights off while resting to save power. A coloured light also does not prove that a new location reached the server: check the latest successful communication in the app or portal.</p><h2 id="if-the-pattern-is-unexpected" tabindex="-1">If the pattern is unexpected <a class="header-anchor" href="#if-the-pattern-is-unexpected" aria-label="Permalink to &quot;If the pattern is unexpected&quot;">​</a></h2><p>Check charge, mobile coverage and the latest communication time. For a GPS test, use a clear view of the sky. If a pattern persists, charging does not progress, or the device stops communicating, <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">contact support</a> with:</p><ul><li>Product code and device ID, plus firmware version if known.</li><li>Whether the device is charging or has just started.</li><li>The latest successful communication time.</li><li>A short video showing the order, colour and timing of the lights.</li></ul><p>Manufacturing tests, recovery modes and custom applications have separate instructions. This guide covers ordinary device operation.</p>',14)])])}const f=a(s,[["render",o]]);export{u as __pageData,f as default};
